-- Definitive consolidated budgets, separate from contracts, State and ESA accounts.
CREATE TABLE public.autonomic_liquidation (
 territory text NOT NULL CHECK (territory IN ('ANDALUCIA','ARAGON','ASTURIAS','ILLES_BALEARS','CANARIAS','CANTABRIA','CASTILLA_Y_LEON','CASTILLA_LA_MANCHA','CATALUNYA','EXTREMADURA','GALICIA','MADRID','MURCIA','NAVARRA','PAIS_VASCO','LA_RIOJA','COMUNITAT_VALENCIANA')),
 year integer NOT NULL CHECK (year=2024),
 chapter text NOT NULL CHECK (chapter IN ('1','2','3','4','5','6','7','8','9','NF','FIN','TOTAL')),
 initial numeric(18,3) CHECK (initial>=0 AND initial<>'NaN'::numeric),
 credit numeric(18,3) CHECK (credit>=0 AND credit<>'NaN'::numeric),
 obligations numeric(18,3) CHECK (obligations>=0 AND obligations<>'NaN'::numeric),
 payments numeric(18,3) CHECK (payments>=0 AND payments<>'NaN'::numeric),
 unit text NOT NULL CHECK (unit='MILES_EUR'),
 raw_data jsonb NOT NULL,
 PRIMARY KEY(territory,year,chapter),
 CHECK (chapter NOT IN ('NF','FIN','TOTAL') OR (initial IS NOT NULL AND credit IS NOT NULL AND obligations IS NOT NULL AND payments IS NOT NULL))
);
ALTER TABLE public.autonomic_liquidation ENABLE ROW LEVEL SECURITY;
CREATE POLICY autonomic_liquidation_read ON public.autonomic_liquidation FOR SELECT TO anon,authenticated USING(true);
GRANT SELECT ON public.autonomic_liquidation TO anon,authenticated;
GRANT ALL ON public.autonomic_liquidation TO service_role;
